    {
        if (*(u16 *)p != 0)
        {
            *(u16 *)(p + 0x4) = *(u16 *)(p + 0x4) + (*(u16 *)(p + 0xA) + step_x);
            *(u16 *)(p + 0x6) = *(u16 *)(p + 0x6) + (*(u16 *)(p + 0xC) + step_y);
            *(u16 *)(p + 0x8) = *(u16 *)(p + 0x8) + (*(u16 *)(p + 0xE) + step_z);
