                }
                *(u16 *)(p + 0x2) = *(u16 *)(p + 0x16);
            }
            if (*(u8 *)(p + 0x14) != 0)
            {
                *(u8 *)(p + 0x14) = *(u8 *)(p + 0x14) + *(u8 *)(p + 0x15);
            }
