                }
                hud->r = 250;
                hud->g = 50;
                hud->b = 10;
                hud->a = 255;
            } else if (car->info->done == 0) {
                car = hud->owner->node;
                carId = car->info->id;
                if (carId == hud->id) {
                    hud->r = 254;
                    hud->g = 213;
                    hud->b = 30;
                    hud->a = 255;
                } else {
                    hud->r = 255;
                    hud->g = 255;
                    hud->b = 255;
                    hud->a = 255;
                }
            }
        }
    }
}

