  u16 *car_ids;
  Db40 *db_root;
  Car40 *cars_db;
  s32 *cls_next;
  s32 *cls_cur;
  s32 picked;
  u32 car;
  s32 unique;

  ncars = gTexPackCount;
  nplayers = gRecords->nplayers;
  car_ids = gRecords->car;
  db_root = &D_800D05E0;
  rand_seed(osGetTime());
  if (ncars == 0)
    return;
