  {
    car_ids[i] = gRecords->pl[gRecords->slot[i]].car;
    if (gRecords->pl[gRecords->slot[i]].name[0] == 0)
    {
      format_to_buffer(name_buf, D_800A4C20, D_800A4C28, i + 1);
      *(s32 *) gRecords->pl[gRecords->slot[i]].name = name_buf[0];
