  if (gRecords->flag == 0)
    return;
  cars_db = db_root->cars;
  for (i = 0; i < nplayers; i++)
    classes[i] = cars_db[gRecords->pl[gRecords->slot[i]].car].cls;
  i = nplayers;
  if (i < 4)
  {
    cls_next = classes;
    do
    {
      switch (gRecords->nplayers)
      {
        case 1:
          if (classes[0] == 2)
            classes[0] = 0;
          picked = 0;
          cls_cur = cls_next;
          slot = i;
          do
          {
            car = rand_next15() % ncars;
            unique = 1;
            if (cars_db[car].cls == *cls_cur)
            {
              u32 lim = slot;
              for (k = 0; k < lim; k++)
                unique &= -(car_ids[k] != car);
              if (unique && !(cars_db[car].flags & 8))
              {
                car_ids[slot] = car;
                picked = 1;
                record_slot_init(gRecords->slot[slot], car & 0xFF);
              }
            }
          }
          while (!picked);
          break;
        case 2:
          if (classes[0] == 2)
            classes[0] = 0;
          if (classes[1] == 2)
            classes[1] = 0;
          picked = 0;
          slot = i;
          do
          {
            car = rand_next15() % ncars;
            unique = 1;
            if (cars_db[car].cls == *cls_next)
            {
              u32 lim = slot;
              for (k = 0; k < lim; k++)
                unique &= -(car_ids[k] != car);
              if (unique && !(cars_db[car].flags & 8))
              {
                picked = 1;
                car_ids[slot] = car;
                record_slot_init(gRecords->slot[slot], car & 0xFF);
                cls_next++;
              }
            }
          }
          while (!picked);
          break;
        case 3:
          break;
      }
      i++;
    }
    while (i < 4);
