/* Scans pool[0..count) for the first object whose flags bit 0 is clear, sets that
 * bit to reserve it and returns it. Returns NULL if every object is already reserved. */
Obj *findAndReserveObj(Obj *pool, s32 count)
{
  while (count != 0)
  {
    if (!(pool->flags & 1))
    {
      pool->flags |= 1;
      return pool;
    }
    pool++;
    count--;
  }
  return 0;
}

