/* Starts a controller status query on the message queue mq. If __osPfsLastCmd is set, it first
 * packs and writes a request to PIF RAM and waits for the reply on mq. Then it reads the
 * PIF RAM result, clears __osPfsLastCmd, and returns the read's status. */
s32 osContStartQuery(s32 mq)
{
    s32 result;

    pif_lock();
    if (__osPfsLastCmd != 0) {
        __osPackRequestData(0);
        __osSiRawStartDma(1, __osContPifRam);
        osRecvMesg(mq, 0, 1);
    }
    result = __osSiRawStartDma(0, __osContPifRam);
    __osPfsLastCmd = 0;
    pif_unlock();
    return result;
}

