	mf[1][2] = bc + (x * sine);

	t = y * y;
	mf[1][1] = t + cosine * (1 - t);
	mf[2][0] = ca + (y * sine);
	mf[0][2] = ca - (y * sine);

	t = z * z;
	mf[2][2] = t + cosine * (1 - t);
	mf[1][0] = ab - (z * sine);
	mf[0][1] = ab + (z * sine);
}

