 * command output of each source filter in the bus. */
Acmd *alAuxBusPull(void *filter, s16 *outp, s32 outCount, s32 sampleOffset, Acmd *p)
{
    Acmd *ptr = p;
    ALAuxBus *bus = (ALAuxBus *)filter;
    ALFilter **sources = bus->sources;
    s32 i;

    {
