        cmd->words.w1 = (unsigned int)(outCount << 1);
    }
    {
        Acmd *cmd = (Acmd *)ptr++;
        cmd->words.w0 = (2u << 24) | 2048;
        cmd->words.w1 = (unsigned int)(outCount << 1);
    }

