/* Computes the low-pass filter gain and the 16-tap decay coefficient table for a lowpass effect from its cutoff frequency fc, and resets the filter's first-sample flag. */ void alFxFillDecay (ALLowPass *lp)
{
    s32		i, temp;
    s16		fc;
    f64		ffc, fcoef;

    temp = lp->fc * 16384 ;
    fc = temp >> 15;
    lp->fgain = 16384  - fc;

    lp->first = 1;
    for (i=0; i<8; i++)
	lp->fcvec.fccoef[i] = 0;

