f64
_frexpf(f64 x, s32 *exponent)
{
    f64 mantissa;

    /* Split x into mantissa in [0.5, 1) and a power of two in *exponent; the sign is kept. */
    *exponent = 0;
    if (x == 0.0)  
        return (x);
    mantissa = (x > 0.0) ? x : -x;
    for ( ; mantissa >= 1.0; mantissa *= 0.5)
        ++*exponent;
    for ( ; mantissa < 0.5; mantissa += mantissa)
        --*exponent;
    return (x > 0.0 ? mantissa : -mantissa);
}

