/* Splits x into integer and fractional parts. The integer part is stored in
 * *iptr (as a double) and the fractional part is returned. */
f64 modf(f64 x, void *iptr) {
    s32 exp;
    s32 e;
    s32 t;
    s32 idx;
    u8 *p;
    u8 *q;

    *(f64 *)iptr = x;
    exp = (*(u32 *)iptr >> 20) & 0x7FF;
    e = exp - 0x3FF;
    if (e < 0) {
        *(f64 *)iptr = 0.0;
        return x;
    }
    if (e >= 0x34) {
        *(f64 *)iptr = x;
        return 0.0;
    }
    t = exp - 0x3F3;
    idx = t >> 3;
    p = (u8 *)iptr + idx;
    *p &= 0xFF << (8 - (t & 7));
    if (idx < 7) {
        q = p;
        do {
            q++;
            *q = 0;
#ifdef PORT
        } while (q < (u8 *)iptr + 7);
#else
        } while ((s32)q < (s32)((u8 *)iptr + 7));
#endif
    }
    return x - *(f64 *)iptr;
}

